// Some portions generated by Claude
package org.eclipse.rdf4j.workbench.commands;

import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.Mockito.mock;

import java.util.ArrayList;
import java.util.List;

import org.eclipse.rdf4j.common.iteration.Iterations;
import org.eclipse.rdf4j.repository.Repository;
import org.eclipse.rdf4j.repository.RepositoryConnection;
import org.eclipse.rdf4j.repository.manager.RepositoryManager;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.sail.memory.MemoryStore;
import org.eclipse.rdf4j.workbench.support.TestServletConfig;
import org.eclipse.rdf4j.workbench.util.WorkbenchPageProtocol;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.mock.web.MockHttpServletRequest;
import org.springframework.mock.web.MockHttpServletResponse;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;

/**
 * The Namespaces page (plan task M6.3, mockup 07): explicit save and delete actions with validation, and a listing in
 * prefix order.
 */
class NamespacesServletPageDataTest {

	private static final ObjectMapper JSON_MAPPER = new ObjectMapper();

	private Repository repository;

	private NamespacesServlet servlet;

	@BeforeEach
	void setUp() throws Exception {
		repository = new SailRepository(new MemoryStore());
		repository.init();
		try (RepositoryConnection connection = repository.getConnection()) {
			connection.setNamespace("dc", "http://purl.org/dc/elements/1.1/");
			connection.setNamespace("rdfs", "http://www.w3.org/2000/01/rdf-schema#");
			connection.setNamespace("bsbm", "http://www4.wiwiss.fu-berlin.de/bizer/bsbm/v01/vocabulary/");
		}
		servlet = new NamespacesServlet();
		servlet.setRepository(repository);
		servlet.setRepositoryManager(mock(RepositoryManager.class));
		servlet.init(TestServletConfig.withParams("namespaces", "cookie-max-age", "300"));
	}

	@AfterEach
	void tearDown() {
		servlet.destroy();
		repository.shutDown();
	}

	@Test
	void listingIsSortedByPrefix() throws Exception {
		MockHttpServletResponse response = new MockHttpServletResponse();

		servlet.service(request("GET"), response);

		assertThat(column(records(response), 0)).containsExactly("bsbm", "dc", "rdfs");
	}

	@Test
	void saveWithAPreviousPrefixRenamesTheNamespace() throws Exception {
		MockHttpServletRequest request = request("POST");
		request.addParameter("action", "save");
		request.addParameter("prefix", "dcterms");
		request.addParameter("namespace", "http://purl.org/dc/terms/");
		request.addParameter("previousPrefix", "dc");
		MockHttpServletResponse response = new MockHttpServletResponse();

		servlet.service(request, response);

		assertThat(response.getRedirectedUrl()).isEqualTo("namespaces");
		assertThat(namespaces()).contains("dcterms=http://purl.org/dc/terms/").noneMatch(ns -> ns.startsWith("dc="));
	}

	@Test
	void deleteRemovesThePrefix() throws Exception {
		MockHttpServletRequest request = request("POST");
		request.addParameter("action", "delete");
		request.addParameter("prefix", "dc");
		MockHttpServletResponse response = new MockHttpServletResponse();

		servlet.service(request, response);

		assertThat(response.getRedirectedUrl()).isEqualTo("namespaces");
		assertThat(namespaces()).noneMatch(ns -> ns.startsWith("dc="));
	}

	@Test
	void anInvalidPrefixAnswersBadRequestAndChangesNothing() throws Exception {
		MockHttpServletRequest request = request("POST");
		request.addParameter("action", "save");
		request.addParameter("prefix", "not a prefix");
		request.addParameter("namespace", "http://example.org/");
		MockHttpServletResponse response = new MockHttpServletResponse();

		servlet.service(request, response);

		assertThat(response.getStatus()).isEqualTo(400);
		assertThat(errorMessage(records(response))).contains("not a prefix");
		assertThat(namespaces()).hasSize(3);
	}

	@Test
	void aRelativeNamespaceAnswersBadRequest() throws Exception {
		MockHttpServletRequest request = request("POST");
		request.addParameter("action", "save");
		request.addParameter("prefix", "ex");
		request.addParameter("namespace", "relative/path#");
		MockHttpServletResponse response = new MockHttpServletResponse();

		servlet.service(request, response);

		assertThat(response.getStatus()).isEqualTo(400);
		assertThat(errorMessage(records(response))).contains("relative/path#");
		assertThat(namespaces()).noneMatch(ns -> ns.startsWith("ex="));
	}

	@Test
	void aLegacyPostWithoutANamespaceAnswersBadRequest() throws Exception {
		MockHttpServletRequest request = request("POST");
		request.addParameter("prefix", "dc");
		MockHttpServletResponse response = new MockHttpServletResponse();

		servlet.service(request, response);

		assertThat(response.getStatus()).isEqualTo(400);
		assertThat(errorMessage(records(response))).isNotEmpty();
		assertThat(namespaces()).hasSize(3);
	}

	private List<String> namespaces() {
		try (RepositoryConnection connection = repository.getConnection()) {
			return Iterations.asList(connection.getNamespaces())
					.stream()
					.map(ns -> ns.getPrefix() + "=" + ns.getName())
					.toList();
		}
	}

	private static MockHttpServletRequest request(String method) {
		MockHttpServletRequest request = new MockHttpServletRequest(method, "/namespaces");
		request.addHeader("Accept", WorkbenchPageProtocol.ACCEPT);
		return request;
	}

	private static List<JsonNode> records(MockHttpServletResponse response) throws Exception {
		return response.getContentAsString().lines().map(NamespacesServletPageDataTest::readTree).toList();
	}

	private static JsonNode readTree(String line) {
		try {
			return JSON_MAPPER.readTree(line);
		} catch (Exception e) {
			throw new IllegalStateException(e);
		}
	}

	private static String errorMessage(List<JsonNode> records) {
		return records.stream()
				.filter(record -> "metadata".equals(record.path("type").asText()))
				.map(record -> record.path("values").path("error-message").asText())
				.filter(message -> !message.isEmpty())
				.findFirst()
				.orElse("");
	}

	private static List<String> column(List<JsonNode> records, int index) {
		List<String> values = new ArrayList<>();
		for (JsonNode record : records) {
			if ("rows".equals(record.path("type").asText())) {
				record.path("values").forEach(row -> values.add(row.get(index).path("value").asText()));
			}
		}
		return values;
	}
}
